"""Original crystal arthritis questions: gout diagnosis and treatment."""
from qbank_authoring import question,ref
rows=[]
G=ref('ACR 2020 gout management guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC10563586/')
IM=ref('EULAR imaging in crystal-induced arthropathies: 2023 recommendations, published 2024','https://pmc.ncbi.nlm.nih.gov/articles/PMC11103298/')
CP=ref('ACR/EULAR 2023 CPPD classification criteria','https://pmc.ncbi.nlm.nih.gov/articles/PMC10543651/')
def q(stem,answer,others,title,principle,details,application,clinical,table,refs,style='direct'):
    rows.append(question(stem,answer,others,title,principle,details,application,clinical,table,refs,style))

q('A man develops abrupt severe first-MTP pain and swelling overnight. Aspirate contains intracellular needle-shaped strongly negatively birefringent crystals. What is the diagnosis?', 'Monosodium urate crystal arthritis',[
 ('Calcium pyrophosphate crystal arthritis','CPP crystals are usually rhomboid or rod-shaped with weak positive birefringence.'),('Basic calcium phosphate crystal arthritis','These crystals are generally too small and nonbirefringent for routine polarized-light identification.'),('Cholesterol crystal synovitis','Cholesterol crystals have a different plate-like morphology, often with notched corners.')],
 'Identify the crystal rather than relying only on the joint site','**Needle-shaped negatively birefringent monosodium urate crystals establish urate deposition.**',['Podagra is characteristic but does not replace aspiration when the diagnosis is uncertain.','Crystal detection does not exclude simultaneous infection.'], '**Send microbiology when septic arthritis remains a concern.**',['Interpret cell counts with the clinical presentation.','Plan flare treatment and assess the indication for long-term urate lowering separately.'],[['MSU','Needle-shaped, negative birefringence'],['CPP','Often rhomboid, weak positive'],['BCP','Not reliably seen by routine polarized microscopy']],[IM],style='clinical_scenario')

q('A patient has classic acute podagra but serum urate is 5.7 mg/dL during the attack. Which interpretation is best?', 'A normal serum urate during a flare does not exclude gout',[
 ('The value excludes all urate deposition','Urate can fall during acute inflammation.'),('The value proves CPPD','CPPD requires its own clinical, crystal or imaging evidence.'),('The value establishes septic arthritis','Serum urate cannot establish an infectious cause.')],
 'Separate a transient serum measurement from deposited crystal burden','**Acute gout can occur with a serum urate in the laboratory reference range.**',['The diagnosis is strongest when supported by crystal identification in an appropriate sample.','Repeat urate after the acute episode when assessing chronic management.'], '**Do not discard a convincing diagnosis on this measurement alone.**',['Maintain infection assessment when clinical findings warrant it.','A persistently raised urate without symptoms is a different clinical category.'],[['During a flare','Urate can be temporarily lower'],['Crystal analysis','Direct evidence of deposition'],['Repeat measurement','Helps long-term management']],[G,IM],style='clinical_scenario')

q('Which ultrasound finding is particularly associated with urate deposition on the surface of articular cartilage?', 'Double-contour sign',[
 ('Chondrocalcinosis within cartilage','This more often supports CPP deposition in the appropriate context.'),('Pencil-in-cup change','This is a structural pattern associated with severe psoriatic arthritis.'),('Central gull-wing erosion','This is more characteristic of erosive osteoarthritis.')],
 'Recognize the location of crystal deposition','**The gout double-contour sign represents an abnormal echogenic surface over cartilage.**',['Tophi and dual-energy CT urate signals are other useful deposition findings.','Artifacts and other deposits can complicate interpretation, so expertise and clinical correlation matter.'], '**Use imaging when aspiration is not feasible or additional characterization is needed.**',['A positive deposition image does not prove every new hot joint is a gout flare.','Aspirate when infection or another acute cause is a concern.'],[['Gout ultrasound','Double contour or tophi'],['CPPD imaging','Cartilage calcification'],['DECT','Can identify urate deposits']],[IM])

q('Which process initiates the acute inflammatory response to monosodium urate crystals?', 'Innate immune activation involving the NLRP3 inflammasome and IL-1 signaling',[
 ('A type I IgE reaction to urate crystals','Gout is not principally an immediate IgE-mediated allergy.'),('An isolated deficiency of terminal complement components','This is not the defining trigger for an acute gout attack.'),('Anti-CCP binding to the crystal surface as the required first event','ACPA is not required for gout inflammation.')],
 'Crystals activate innate inflammatory pathways','**MSU crystals can trigger inflammasome-mediated IL-1 production and neutrophilic inflammation.**',['The deposited material is present between attacks even when acute inflammation resolves.','Inflammation control and crystal-burden reduction therefore answer different treatment goals.'], '**Use anti-inflammatory therapy for a flare and urate lowering for long-term disease control when indicated.**',['Colchicine interferes with microtubule-dependent inflammatory functions.','IL-1-directed treatment has a selected role when usual flare therapies cannot be used.'],[['Flare treatment','Suppress inflammation'],['Urate lowering','Reduce crystal burden over time'],['IL-1 pathway','Relevant inflammatory mediator']],[ref('MSU/CPP crystals activate the NALP3 inflammasome: original study','https://doi.org/10.1038/nature04516')])

q('A patient with an acute gout flare has advanced CKD, recent gastrointestinal bleeding and poorly controlled heart failure. Infection has been excluded from a single accessible inflamed knee. Which option is especially reasonable?', 'Intra-articular glucocorticoid after appropriate aspiration',[
 ('High-dose indomethacin','Renal, gastrointestinal and heart-failure risks make this unattractive.'),('High-dose colchicine repeated until diarrhea occurs','This old strategy is toxic, especially with renal impairment.'),('A large initial allopurinol dose as the only immediate analgesic treatment','Allopurinol does not provide rapid anti-inflammatory pain control.')],
 'Select flare therapy by comorbidity and joint distribution','**A local glucocorticoid can control an isolated flare when systemic options are hazardous.**',['Infection must be excluded before injection.','Systemic glucocorticoids or carefully selected low-dose colchicine may be alternatives in other clinical circumstances.'], '**Review renal function, interactions and cardiovascular risk.**',['Treat early and provide practical follow-up.','Recurrent flares should prompt a long-term urate-lowering discussion.'],[['NSAID','Renal/GI/heart-failure concerns'],['Colchicine','Dose and interaction constraints'],['Local glucocorticoid','Useful for an appropriate single joint']],[G],style='clinical_scenario')

q('A patient taking colchicine develops vomiting, proximal weakness and cytopenias after starting clarithromycin, with renal impairment. What is the most likely explanation?', 'Colchicine accumulation from CYP3A4/P-glycoprotein inhibition',[
 ('A protective interaction that increases urate excretion','The interaction increases toxicity rather than reliably improving gout control.'),('An allopurinol hypersensitivity reaction despite no allopurinol exposure','The exposure history does not support this cause.'),('An isolated inflammatory gout flare causing marrow suppression','A flare does not adequately explain this systemic drug-toxicity syndrome.')],
 'Colchicine has a narrow safety margin','**Strong metabolic/transporter inhibitors can cause life-threatening colchicine toxicity.**',['Renal or hepatic impairment further increases concern.','GI symptoms may precede neuromuscular and marrow toxicity.'], '**Stop implicated treatment and arrange urgent toxicity assessment.**',['Review every interacting drug before prescribing colchicine.','Avoid assuming that a familiar low-dose drug is safe in all combinations.'],[['Clarithromycin','Strong interaction potential'],['Renal impairment','Reduces safety margin'],['Weakness/cytopenias','Possible systemic colchicine toxicity']],[ref('FDA colchicine prescribing information','https://www.accessdata.fda.gov/drugsatfda_docs/label/2009/022352lbl.pdf')],style='clinical_scenario')

q('Which patient has a strong indication for long-term urate-lowering therapy under the ACR gout guideline?', 'A patient with subcutaneous tophi and recurrent flares',[
 ('A patient with one incidental urate of 7.1 mg/dL and no gout history','Asymptomatic hyperuricemia alone usually does not justify routine pharmacological ULT.'),('A patient with isolated radiographic chondrocalcinosis and normal urate','This suggests CPPD, not an indication for urate lowering.'),('A patient with a transient creatinine rise but no gout or urate stones','This does not establish a gout-specific ULT indication.')],
 'Identify clinically important urate deposition disease','**Tophi, gout-related radiographic damage and frequent flares are strong reasons to start ULT.**',['Selected first-flare patients may also merit treatment, such as those with CKD stage 3 or worse, very high urate or urolithiasis.','The decision should reflect the whole gout history and patient preferences.'], '**Explain the difference between sustained prevention and flare treatment.**',['ULT reduces the deposited urate burden gradually.','Initial mobilization flares do not mean the long-term strategy has failed.'],[['Tophi/frequent flares','Strong indication'],['Selected first flare with high-risk features','Discuss ULT'],['Asymptomatic hyperuricemia','Usually no routine ULT']],[G])

q('A patient with gout and stage 3 CKD needs ULT. Which allopurinol strategy is most appropriate?', 'Start at a low dose, lower when appropriate for CKD, and titrate using serial urate and safety assessment',[
 ('Never use allopurinol in CKD','Allopurinol remains a preferred initial option even in CKD when prescribed appropriately.'),('Start at a high dose to reach the target immediately','A high starting dose increases adverse-event concerns.'),('Maintain every CKD patient permanently at 50 mg regardless of persistent hyperuricemia','A cautious starting dose is not necessarily the final effective dose.')],
 'Start low and titrate to an effect','**CKD changes safe initiation and monitoring, not the fundamental need for effective urate control.**',['Assess hypersensitivity risk and relevant ancestry-based HLA-B*58:01 testing recommendations.','Dose escalation can be undertaken cautiously while monitoring renal function and other adverse effects.'], '**Use a treat-to-target plan rather than a fixed ineffective dose.**',['Provide flare prophylaxis when appropriate.','Educate about rash, fever and mucosal or systemic symptoms requiring urgent review.'],[['Starting dose','Low and individualized'],['Maintenance dose','Titrated to response/tolerance'],['CKD','Requires extra safety attention']],[G],style='clinical_scenario')

q('For most patients receiving ULT for gout, what serum urate target is recommended by ACR?', 'Below 6 mg/dL',[
 ('Below 9 mg/dL','This remains above the usual saturation range and target.'),('Below 8 mg/dL','This is not the usual treatment target.'),('Below 7 mg/dL','This can still be above the saturation threshold and is not the ACR target.')],
 'Maintain urate below the target long enough to reduce deposits','**Serial serum urate guides dose adjustment toward a value below 6 mg/dL.**',['Some other guidelines use lower targets in severe tophaceous disease.','The treatment effect on tophi and flares takes time even after reaching the biochemical target.'], '**Monitor adherence and titrate rather than judge solely by a single flare.**',['Address tolerability and access barriers.','Diet and weight management support treatment but often cannot replace ULT in established high-burden gout.'],[['ACR usual target','<6 mg/dL'],['Persistent above-target urate','Review adherence/dose'],['Clinical improvement','Often follows gradually']],[G])

q('A patient who is stable on allopurinol develops a gout flare. Which approach is usually appropriate?', 'Continue established allopurinol and treat the flare with an appropriate anti-inflammatory',[
 ('Stop allopurinol during every attack and restart only after several weeks','Repeated interruption destabilizes urate control.'),('Double allopurinol immediately as the sole flare analgesic','The drug is not an immediate anti-inflammatory.'),('Permanently stop ULT because a flare proves lack of benefit','Flares can occur during the period of crystal mobilization or incomplete control.')],
 'Do not confuse a flare with a reason to abandon prevention','**Established ULT is generally continued through a flare.**',['Select NSAID, colchicine or glucocorticoid therapy according to patient factors.','Initiating ULT during a flare can also be appropriate when indicated, provided flare treatment is addressed.'], '**Review whether long-term urate control is adequate after the acute episode.**',['Check adherence and serial urate results.','Persistent frequent flares may require adjustment of the prevention strategy.'],[['Existing ULT','Usually continue'],['Acute flare','Add suitable anti-inflammatory treatment'],['Long-term review','Target, adherence and crystal burden']],[G],style='clinical_scenario')

q('Why is anti-inflammatory prophylaxis commonly prescribed when ULT is initiated?', 'Changing urate levels can mobilize deposits and trigger early flares',[
 ('Allopurinol directly kills bacteria in tophi','ULT does not provide antibacterial therapy.'),('Every early flare represents an allopurinol allergy','An ordinary flare is distinct from a systemic hypersensitivity reaction.'),('ULT cannot lower serum urate unless colchicine is coadministered','Colchicine controls inflammation rather than enabling xanthine oxidase inhibition.')],
 'Prevent early flares while long-term benefit develops','**An initial increase in attacks can occur as urate deposits begin to change.**',['Low-dose colchicine, an NSAID or selected glucocorticoid prophylaxis may be used according to comorbidity.','ACR recommends prophylaxis for at least three to six months with further assessment if flares continue.'], '**Explain the time course before treatment starts.**',['This improves adherence when an early flare occurs.','Review toxicity and interactions rather than continue prophylaxis automatically without reassessment.'],[['ULT','Reduces urate burden'],['Prophylaxis','Reduces early inflammation'],['Follow-up','Duration depends on continuing activity and risk']],[G])

q('A patient who is HLA-B*58:01 positive needs a new ULT prescription. Which choice should usually be avoided?', 'Allopurinol',[
 ('Febuxostat solely because HLA-B*58:01 positivity directly predicts its hypersensitivity','The established association is with allopurinol; febuxostat has separate safety considerations.'),('Colchicine solely because this allele predicts colchicine myotoxicity','This is not the recognized pharmacogenetic association.'),('A local glucocorticoid solely because of this allele','HLA-B*58:01 is not the defining contraindication to local steroid therapy.')],
 'Recognize a specific severe cutaneous adverse-reaction association','**HLA-B*58:01 is strongly associated with allopurinol severe hypersensitivity reactions.**',['Testing is particularly relevant in higher-prevalence ancestry groups and according to local recommendations.','A negative test does not eliminate every possible adverse reaction.'], '**Choose an alternative with its own comorbidity assessment.**',['Do not substitute without reviewing cardiovascular, renal and drug-interaction issues.','Any new severe rash with mucosal or systemic symptoms requires urgent evaluation.'],[['HLA-B*58:01','Allopurinol hypersensitivity risk'],['Negative test','Not a guarantee of complete safety'],['Alternative ULT','Assess separate risks']],[G])

if __name__=='__main__':print(f'Crystal arthritis draft: {len(rows)} questions')
